 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] != 0:
                        seen.add((ny,nx)); q.append((ny,nx))
            counts = Counter(grid[y][x] for y, x in cells)
            # Concentric color bands are ordered from largest/outermost to smallest/innermost;
            # reverse this order, as demonstrated by each object.
            bands = sorted(counts, key=lambda color: counts[color], reverse=True)
            mapping = dict(zip(bands, reversed(bands)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
